-- ve-demo-showroom: Green Leaf tour v3 frames in the lookbook (2026-11-08). Replaces the 60 v2 frames (Sean's notes on them are in
-- 20261108_green_leaf_tour_lookbook_notes.sql). 25 frames, about 5 s each, no zoom: the real phone frame on a white stage with headroom, the
-- Sample stamp top-left, and scenes from the sample's own photos. Stills in vegan-media/media/tours/green-leaf-tour/v3-NN.jpg. Applied through the connector.
delete from ve_video_shots where tour_id=(select id from ve_video_tours where slug='green-leaf-tour');
insert into ve_video_shots (tour_id,chapter_n,ord,kind,brief,image_url,audio_from,audio_to,status,readiness,line)
select t.id,v.ch,v.o,v.kind,v.brief,v.img,v.af,v.at,'proposed','ready',v.line from ve_video_tours t,(values
(1,1,'illustration','V in the café with the tablet, her tour picture. Held still about 6.5 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-01.jpg?v=1',0,6.0,'Hi, I''m V. This is Green Leaf Kitchen. It''s not a real restaurant. It''s our sample,'),
(1,2,'screen','The home page as it opens on a phone: header, Open now, the headline. Held still about 5.1 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-02.jpg?v=1',6.0,11.06,'built to show you what a Vegan restaurant''s website can look like when we build it with you.'),
(1,3,'screen','The tour page on a phone: V, Play the tour and Talk to our team. Held still about 4.4 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-03.jpg?v=1',11.06,15.4645,'Watch the tour, then tap around. Nothing you do here is saved'),
(2,1,'screen','The first screen''s buttons and the Today strip: hours and address. Held still about 6.4 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-04.jpg?v=1',0,6.36,'The first screen answers what people want to know. Are you open? What''s good? And how do I order?'),
(2,2,'screen','Favorites, ranked by member votes, the heart pressed on the first card. Held still about 5.3 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-05.jpg?v=1',6.36,11.7029,'The favorites row is ranked by what members vote for, so it stays current on its own.'),
(3,1,'screen','Our story, with the story video on the page. Held still about 5.5 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-06.jpg?v=1',0,5.47,'People choose a restaurant for the people behind it. Your story plays right on the page,'),
(3,2,'screen','The space in four photos: by day, at night, inside, the team. Held still about 4.4 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-07.jpg?v=1',5.47,9.8743,'and your space shows by day, at night, inside, and with your team.'),
(4,1,'screen','A dish page: Sunrise Plate, its photos, price and description. Held still about 5.5 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-08.jpg?v=1',0,5.55,'Every dish has its own page, allergens, a nutrition estimate, and what''s in it'),
(4,2,'screen','What''s in it, and where it comes from: each ingredient with its maker or farm. Held still about 6.4 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-09.jpg?v=1',5.55,11.9641,'with where each ingredient comes from. When it''s a brand in our Directory, it links to that brand''s page.'),
(5,1,'screen','Sign in with Vegans Explore. Held still about 5.0 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-10.jpg?v=1',0,4.98,'Members of Vegans Explore can sign in here with the account they already have.'),
(5,2,'screen','The dish as a signed-in member: vote and Save. Held still about 5.4 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-11.jpg?v=1',4.98,10.3967,'They vote for their favorite dishes once a day and save the ones they want to come back for.'),
(6,1,'screen','The owner''s view: the bar that says you are viewing your site as the owner. Held still about 4.1 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-12.jpg?v=1',0,4.11,'Switch to the owner and the same page becomes yours to update.'),
(6,2,'screen','The owner editing what is in the dish. Held still about 5.2 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-13.jpg?v=1',4.11,9.3257,'Change an ingredient, add a brand from our Directory, and the dish page shows it'),
(7,1,'screen','Order for pickup: items added with the stepper. Held still about 4.9 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-14.jpg?v=1',0,4.93,'Ordering is short. Add what you want, choose pickup, and pay.'),
(7,2,'screen','Scene: the kitchen counter (the sample''s own photo). Held still about 4.6 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-15.jpg?v=1',4.93,9.53,'When your point of sale is connected, orders go straight to your kitchen.'),
(7,3,'screen','Your order: the cart, pickup, delivery coming soon. Held still about 3.0 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-16.jpg?v=1',9.53,12.4865,'Vegans Explore Delivery is coming soon'),
(8,1,'screen','Three phones side by side: Their brand, Island bright, Night lounge. Held still about 4.5 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-17.jpg?v=1',0,4.5,'This is one site in three looks. Same menu, same story,'),
(8,2,'screen','The brand kit on a phone. Held still about 4.5 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-18.jpg?v=1',4.5,8.96,'different colors and type. Yours is built from your own brand kit'),
(9,1,'screen','Green Leaf Kitchen''s Vegans Explore page: Vote, Save, Check in. Held still about 7.1 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-19.jpg?v=1',0,7.1053,'Your site connects to your Vegans Explore page, where members find you, vote for you, and check in when they visit.'),
(10,1,'screen','The Community page: Be part of Green Leaf Kitchen, your points. Held still about 5.1 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-20.jpg?v=1',0,5.1,'Your regulars become your community. Members unlock rewards you choose,'),
(10,2,'screen','A reward: a seat at the chef''s table, points and how many are left. Held still about 5.9 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-21.jpg?v=1',5.1,11.04,'like a free drink or a seat at your chef''s table with the points they earn on Vegans Explore.'),
(10,3,'screen','An unlocked reward with its code. Held still about 4.1 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-22.jpg?v=1',11.04,15.18,'There are only so many, first come, first served,'),
(10,4,'screen','The Green Leaf Club, a Guide on Vegans Explore, Join free. Held still about 7.0 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-23.jpg?v=1',15.18,22.1518,'and your club is a Guide on Vegans Explore, so it brings people in and sends them out to the rest of the community'),
(11,1,'screen','Scene: the owner in her restaurant (the sample''s own photo). Held still about 4.7 s, then a soft crossfade.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-24.jpg?v=1',0,4.72,'Want one like this for your restaurant? Tap Talk to our team and a real person'),
(11,2,'illustration','V in the café, held to the end, about 2.8 s with the closing music.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/tours/green-leaf-tour/v3-25.jpg?v=1',4.72,6.3478,'will walk you through it')) v(ch,o,kind,brief,img,af,at,line) where t.slug='green-leaf-tour';
update ve_video_tours set status='lookbook', updated_at=now() where slug='green-leaf-tour';

-- Round 2 (Sean's notes, 2026-11-08): desktop strings in a laptop frame (frames 2-3, 8-9, 18-19), On a phone / On a computer labels,
-- the current night photo in frame 7; every image ?v=2. Applied through ve-once-tour-v3 (now the 410 stub).
update ve_video_shots s set image_url=replace(s.image_url,'?v=1','?v=2'), updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour';
update ve_video_shots s set brief='The home page on a computer: the headline, the buttons and the Today strip. Held still about 5.1 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=1 and s.ord=2;
update ve_video_shots s set brief='The tour page on a computer: V, Start here, Open the demo. Held still about 4.4 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=1 and s.ord=3;
update ve_video_shots s set brief='The space in four photos: by day, at night (the current night photo), inside, the team. Held still about 4.4 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=3 and s.ord=2;
update ve_video_shots s set brief='A dish page on a computer: Sunrise Plate, allergens, nutrition. Held still about 5.5 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=4 and s.ord=1;
update ve_video_shots s set brief='What''s in it, and where it comes from, on a computer. Held still about 6.4 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=4 and s.ord=2;
update ve_video_shots s set brief='The brand kit on a computer: six colors, each with a job. Held still about 4.5 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=8 and s.ord=2;
update ve_video_shots s set brief='Green Leaf Kitchen''s Vegans Explore page on a computer: Vote, Save, About. Held still about 7.1 s, then a soft crossfade.', status='proposed', note=null, updated_at=now() from ve_video_tours t where t.id=s.tour_id and t.slug='green-leaf-tour' and s.chapter_n=9 and s.ord=1;
